"""
    This library contains utilities to manage resources.
"""

from taf.ul.trs_e2e_fw.lib.utils.misc_libraries.hanging_resource.aashell_manager import AaShellManager


def get_resource_usage(**kwargs):
    """
    This keyword fetches resource usage information.

    *Parameters:* \n
    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | detailed | True | (str) - If True, output will be detailed. |  |
    | alias | 'default' | (str) - Name of the execution context. |  |

    *Returns*:
     (dict) - Resource usage parameters.

    *Raises*:
     None

    *Examples*:
    | ${resource_usage1} | Get Resource Usage | alias=alias |
    """
    return AaShellManager().get_resource_usage(**kwargs)


def should_be_equal_as_resources(**kwargs):
    """
    This keyword is used to compare the resource usage at 2 different times.

    *Parameters:* \n
    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | resources_usage | Mandatory | (dict) - Output derived from "Get resource Usage" keyword. |  |
    | exclude | None | (str) - xpath expression to specify which parameters to exclude from the check. |  |
    | fail_on_not_released_resources | True | (bool) - If true keyword will fail when resources are not released. |  |
    | detailed | True | (str) - If True, output will be detailed. |  |
    |  |  | Pass same value as passed in "Get resource Usage" keyword. |  |
    | alias | 'default' | (str) - Name of the execution context. |  |

    *Returns*:
     None

    *Raises*:
     AssertionError: if resource_usage1 is not equal to resource_usage2

    *Examples*:
    | Should Be Equal As Resources | resource_usage=${resource_usage1} | alias=alias |
    """
    return AaShellManager().should_be_equal_as_resources(**kwargs)


def should_all_be_zero(**kwargs):
    """
    This keyword is used to check the resource usage is zero

    *Parameters:* \n
    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | resources_usage | Mandatory | (dict) - Output derived from "Get resource Usage" keyword. |  |
    | path_regex | None | (str) - regular expression for matching XPaths of parameter names. |  |
    |  |  | default: match all parameter names |  |
    | fail_on_not_released_resources | True | (bool) - If true keyword will fail when resources are not released. |  |
    | alias | 'default' | (str) - Name of the execution context. |  |

    *Returns*:
     None

    *Raises*:
     AssertionError: if any one of the resources usage parameter values for paths matched to
     regex not equal 0, all the non-zero resources are returned in the AssertionError args

    *Examples*
    | Should All Be Zero | resource_usage=${resource_usage1} | alias=alias |
    """
    return AaShellManager().should_all_be_zero(**kwargs)